import { Column, CreateDateColumn, Entity, Generated, Index, PrimaryGeneratedColumn, Unique, UpdateDateColumn } from 'typeorm';
import type { OrderStatus } from './order-state';

@Entity('orders')
@Unique(['customer_id', 'client_ref'])
export class Order {
  @PrimaryGeneratedColumn('uuid') id: string;

  // Human number: SM-<seq + 1000>. Generated by the database, so it is gap-tolerant and race-free.
  @Index({ unique: true }) @Column({ type: 'int' }) @Generated('increment') order_seq: number;

  @Index() @Column({ type: 'uuid' }) customer_id: string;
  // Chosen by the browser per checkout attempt: a double-click or retry returns the same order.
  @Column({ type: 'uuid' }) client_ref: string;

  @Index() @Column({ type: 'varchar', length: 20 }) status: OrderStatus;

  // Integer paise. All computed by the server.
  @Column({ type: 'int' }) subtotal_paise: number;
  @Column({ type: 'int', default: 0 }) discount_paise: number;
  @Column({ type: 'int', default: 0 }) delivery_fee_paise: number;
  @Column({ type: 'int', default: 0 }) gift_wrap_paise: number;
  @Column({ type: 'int' }) total_paise: number;
  @Column({ type: 'varchar', length: 30, nullable: true }) coupon_code: string | null;

  @Column({ type: 'bool', default: false }) gift_wrap: boolean;
  @Column({ type: 'text', default: '' }) gift_message: string;
  @Column({ type: 'varchar', length: 30, default: '' }) engraving: string;

  // Address snapshot: later edits to a saved address never change an order already placed.
  @Column({ type: 'varchar', length: 120 }) ship_name: string;
  @Column({ type: 'varchar', length: 14 }) ship_phone: string;
  @Column({ type: 'varchar', length: 200 }) ship_line1: string;
  @Column({ type: 'varchar', length: 200, default: '' }) ship_line2: string;
  @Column({ type: 'varchar', length: 80 }) ship_city: string;
  @Column({ type: 'varchar', length: 60 }) ship_state: string;
  @Column({ type: 'varchar', length: 6 }) ship_pincode: string;

  // Payment (manual UPI): the customer pays, uploads a receipt, an admin verifies it.
  @Column({ type: 'varchar', length: 200, nullable: true }) receipt_key: string | null;
  @Index() @Column({ type: 'varchar', length: 40, nullable: true }) utr: string | null;
  @Column({ type: 'int', nullable: true }) paid_amount_paise: number | null;
  @Column({ type: 'timestamptz', nullable: true }) payment_submitted_at: Date | null;
  @Column({ type: 'timestamptz', nullable: true }) payment_verified_at: Date | null;
  @Column({ type: 'uuid', nullable: true }) payment_verified_by: string | null;
  @Column({ type: 'text', nullable: true }) payment_reject_reason: string | null;

  @Column({ type: 'timestamptz', nullable: true }) packed_at: Date | null;
  @Column({ type: 'varchar', length: 60, nullable: true }) carrier: string | null;
  @Column({ type: 'varchar', length: 80, nullable: true }) tracking_no: string | null;
  @Column({ type: 'timestamptz', nullable: true }) shipped_at: Date | null;
  @Column({ type: 'timestamptz', nullable: true }) delivered_at: Date | null;

  @Column({ type: 'timestamptz', nullable: true }) cancelled_at: Date | null;
  @Column({ type: 'text', nullable: true }) cancel_reason: string | null;
  @Column({ type: 'varchar', length: 10, nullable: true }) cancelled_by: 'customer' | 'admin' | null;
  // Cancelled after the customer may already have paid: money still has to go back.
  @Column({ type: 'bool', default: false }) refund_due: boolean;
  @Column({ type: 'timestamptz', nullable: true }) refunded_at: Date | null;
  @Column({ type: 'text', nullable: true }) refund_note: string | null;

  @Index() @CreateDateColumn({ type: 'timestamptz' }) created_at: Date;
  @UpdateDateColumn({ type: 'timestamptz' }) updated_at: Date;
}

// A snapshot of what was bought, at the price paid. Products can change or vanish; the order does not.
@Entity('order_items')
export class OrderItem {
  @PrimaryGeneratedColumn('uuid') id: string;
  @Index() @Column({ type: 'uuid' }) order_id: string;
  @Column({ type: 'uuid' }) variant_id: string;
  @Column({ type: 'uuid' }) product_id: string;
  @Column({ type: 'varchar', length: 140 }) product_slug: string;
  @Column({ type: 'varchar', length: 40 }) sku: string;
  @Column({ type: 'varchar', length: 140 }) name: string;
  @Column({ type: 'varchar', length: 100 }) brand: string;
  @Column({ type: 'varchar', length: 40 }) label: string;
  @Column({ type: 'int' }) size_ml: number;
  @Column({ type: 'int' }) unit_price_paise: number;
  @Column({ type: 'int' }) qty: number;
  @Column({ type: 'int' }) line_total_paise: number;
  @Column({ type: 'bool', default: false }) is_free_sample: boolean;
  @Column({ type: 'varchar', length: 200, nullable: true }) image_key: string | null;
}

// Append-only history: who moved the order where, and when. This is the audit trail for payment checks.
@Entity('order_events')
export class OrderEvent {
  @PrimaryGeneratedColumn('uuid') id: string;
  @Index() @Column({ type: 'uuid' }) order_id: string;
  @Column({ type: 'varchar', length: 20, nullable: true }) from_status: OrderStatus | null;
  @Column({ type: 'varchar', length: 20 }) to_status: OrderStatus;
  @Column({ type: 'varchar', length: 10 }) actor_type: 'customer' | 'admin' | 'system';
  @Column({ type: 'uuid', nullable: true }) actor_id: string | null;
  @Column({ type: 'text', nullable: true }) note: string | null;
  // e.g. the receipt that was submitted or rejected, so rejected evidence is never lost.
  @Column({ type: 'jsonb', nullable: true }) meta: Record<string, unknown> | null;
  @Index() @CreateDateColumn({ type: 'timestamptz' }) created_at: Date;
}
